"use client";

// Site-wide replaceable icons.
// Every icon on the site has a key ("lucide:ArrowRight", "social:facebook", "service:web-design" …).
// If an icon was uploaded for that key in Sanity → "Icons", the upload is shown instead.
// The list of keys is generated by scripts/icon-manifest.mjs.

import React, { forwardRef } from "react";
import type { LucideIcon, LucideProps } from "lucide-react";

export interface CustomIconData {
  url: string;
  /** true → the uploaded icon is drawn in the website's colour for that spot (like the original line icons) */
  tint: boolean;
}

let ICON_MAP: Record<string, CustomIconData> = {};

/** The uploaded replacement for an icon key, if any. */
export function customIcon(key: string): CustomIconData | undefined {
  return ICON_MAP[key];
}

function setIconMap(value: Record<string, CustomIconData>) {
  ICON_MAP = value || {};
}

/** Sets the replacement map before the page renders (server and browser). */
export function IconProvider({ value, children }: { value: Record<string, CustomIconData>; children: React.ReactNode }) {
  setIconMap(value);
  return <>{children}</>;
}

const HAS_SIZE_CLASS = /(^|\s)(!?)(w|h|size)-/;

/** Draws an uploaded icon in the space the original icon used. */
export function CustomIcon({
  icon,
  className = "",
  style,
  size,
  color,
}: {
  icon: CustomIconData;
  className?: string;
  style?: React.CSSProperties;
  size?: number | string;
  color?: string;
}) {
  const dim = HAS_SIZE_CLASS.test(className) ? {} : { width: size ?? 24, height: size ?? 24 };
  if (!icon.tint) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img src={icon.url} alt="" aria-hidden="true" className={className} style={{ objectFit: "contain", ...dim, ...style }} />
    );
  }
  const mask = `url("${icon.url}") center / contain no-repeat`;
  return (
    <span
      aria-hidden="true"
      className={className}
      style={{
        display: "inline-block",
        flexShrink: 0,
        ...dim,
        backgroundColor: color && color !== "currentColor" ? color : "currentColor",
        mask,
        WebkitMask: mask,
        ...style,
      }}
    />
  );
}

/** Wraps an icon component so it can be replaced from the editor under `key`. */
export function iconSlot(key: string, Original: LucideIcon): LucideIcon {
  const Slot = forwardRef<SVGSVGElement, LucideProps>(function IconSlot(props, ref) {
    const custom = ICON_MAP[key];
    if (!custom) return <Original ref={ref} {...props} />;
    const { className, style, size, color } = props;
    return <CustomIcon icon={custom} className={className} style={style} size={size} color={color} />;
  });
  Slot.displayName = `IconSlot(${key})`;
  return Slot as unknown as LucideIcon;
}
